const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const donnerPass = ee.Geometry.Point([-120.32, 39.34]);
  // Use a small buffer around the point for a more representative average
  const analysisRegion = donnerPass.buffer(1000); // 1 km radius

  const febStart = '2022-02-01';
  const febEnd = '2022-02-28';
  const aprStart = '2022-04-01';
  const aprEnd = '2022-04-30';

  const collectionId = 'NOAA/NOHRSC/SNODAS';
  const bandName = 'SWE'; // Snow Water Equivalent in kg/m^2 (scaled by 10)
  const scale = 1000; // SNODAS resolution is ~1km, so 1000m scale is appropriate

  // Function to process and get mean SWE for a given period
  const getMeanSwe = async (startDate, endDate, periodName) => {
    let collection = ee.ImageCollection(collectionId)
      .filterBounds(analysisRegion)
      .filterDate(startDate, endDate)
      .select(bandName);

    const collectionSize = await collection.size().getInfo();
    console.log(`${periodName} Images: ${collectionSize}`);

    if (collectionSize === 0) {
      return { swe: null, pixels: 0, status: 'C1' };
    }

    // Convert SWE from integer (scaled by 10) to actual SWE in mm (or kg/m^2)
    // Also, mask out values less than 0, as SWE cannot be negative.
    // The SNODAS data commonly uses a scaling factor of 10 for SWE.
    const monthlySwe = collection
      .map(image => image.divide(10).rename(bandName).updateMask(image.select(bandName).gte(0)))
      .mean(); // Average SWE over the period

    // Ensure the image is not null before reducing
    if (!monthlySwe) {
        return { swe: null, pixels: 0, status: 'C3' };
    }

    const stats = await monthlySwe.reduceRegion({
      reducer: ee.Reducer.mean().setOutputs(['mean']),
      geometry: analysisRegion,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326' // Ensure consistent CRS
    }).getInfo();

    const countStats = await monthlySwe.reduceRegion({
      reducer: ee.Reducer.count().setOutputs(['count']),
      geometry: analysisRegion,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326'
    }).getInfo();

    const meanSwe = stats[bandName];
    const validPixels = countStats[bandName];

    if (validPixels === 0) {
      console.log(`No valid pixels remaining for ${periodName} after processing.`);
      return { swe: null, pixels: 0, status: 'C2' };
    }

    if (meanSwe === null || isNaN(meanSwe)) {
      console.log(`Calculation failure for ${periodName}: ${meanSwe}`);
      return { swe: null, pixels: validPixels, status: 'C3' };
    }

    return { swe: meanSwe, pixels: validPixels, status: 'OK' };
  };

  // Get SWE for February
  const febResult = await getMeanSwe(febStart, febEnd, 'February 2022');
  if (febResult.status !== 'OK') {
    console.log(`<answer>${febResult.status}</answer>`);
    return;
  }
  const febSwe = febResult.swe;
  const febPixels = febResult.pixels;

  // Get SWE for April
  const aprResult = await getMeanSwe(aprStart, aprEnd, 'April 2022');
  if (aprResult.status !== 'OK') {
    console.log(`<answer>${aprResult.status}</answer>`);
    return;
  }
  const aprSwe = aprResult.swe;
  const aprPixels = aprResult.pixels;

  // 5. Validation & Final Answer
  console.log(`Donner Pass SWE (Feb 2022): ${febSwe.toFixed(2)} mm (Pixels: ${febPixels})`);
  console.log(`Donner Pass SWE (Apr 2022): ${aprSwe.toFixed(2)} mm (Pixels: ${aprPixels})`);

  if (febSwe === null || aprSwe === null || isNaN(febSwe) || isNaN(aprSwe)) {
    console.log("<answer>C3</answer>");
  } else if (febSwe > aprSwe) {
    console.log("<answer>A</answer>"); // Yes
  } else {
    console.log("<answer>B</answer>"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
